QUIET = NotifyPolicy(desktop=False, file=True)


def triage_result(open_ids, **sections):
    return {
        "workflow": "deferred-sweep-triage",
        "open_ids": list(open_ids),
        "already_resolved": sections.get("already_resolved", []),
        "bundles": sections.get("bundles", []),
        "blocked": sections.get("blocked", []),
        "skip": sections.get("skip", []),
        "decisions": sections.get("decisions", []),
        "escalations": [],
    }


def make_sweep(
    project, script, policy=None, answers=(), prompting=False, run_id="sweep-run", **kwargs
):
    # `run_id` names a DISTINCT run: its own run_dir, state.json and journal.
    # Overridden only where a test needs a second run rather than a resume of the
    # first (run-scoped state, e.g. the DW-124 quarantine).
    run_dir = project.project / ".bmad-loop" / "runs" / run_id
    adapter = MockAdapter(script, usage_per_session=TokenUsage(input_tokens=10, output_tokens=5))
    state = RunState(run_id=run_id, project=str(project.project), started_at="now")
    inputs = iter(answers)
    prompter = DecisionPrompter(input_fn=lambda _: next(inputs), print_fn=lambda _line: None)
    engine = SweepEngine(
        paths=project,
        policy=policy
        or Policy(
            gates=GatesPolicy(mode="none"),
            notify=QUIET,
            scm=ScmPolicy(rollback_on_failure=True),
        ),
        adapter=adapter,
        run_dir=run_dir,
        journal=Journal(run_dir),
        state=state,
        prompting=prompting,
        prompter=prompter,
        **kwargs,
    )
    return engine, adapter


def test_sweep_attaches_journal_to_a_distinct_triage_adapter(project):
    """#680: `Engine.__init__` attaches its journal to the adapters it knows; the
    triage adapter is assigned AFTER that, so a distinct one would otherwise keep
    `journal = None` and every sweep triage session would emit no idle events.

    ABLATION: drop the `self.adapters["triage"].journal = self.journal` line and
    the distinct-adapter assertion reddens."""
    triage = MockAdapter([])
    engine, dev = make_sweep(project, [], triage_adapter=triage)
    assert engine.adapters["triage"] is triage
    assert engine.adapters["triage"].journal is engine.journal
    assert dev.journal is engine.journal


def test_remaining_estimate_is_none_for_an_undecodable_ledger(project):
    """`None` and `0` mean opposite things to the graceful stop, and both are
    PUBLISHED — in the `run-stop` journal row and the stop notice. `None` is "no
    estimate"; `0` is a positive claim that a resume would pick up nothing. Routing
    this read through `read_for_observation` (DW-146) put a fault one `if` away from
    being reported as `0 remaining` for a ledger nobody could read — the fabricated
    answer `cli._sweep_dry_run` refuses to print. The fault is checked, not
    discarded.
    The READ's fault is also JOURNALED, not merely checked. The observation arm
    journals its fault wherever a journal is in hand, and one is in hand here. Note
    the scope: `run-stop` publishes `remaining: null` either way, and the outer
    guard still answers `None` silently for anything raised AFTER the read, so the
    row does not make every null self-explaining — what it buys is that the one
    fault class the arm hands back as a VALUE gets attributed instead of collapsing
    into that same silence.
    Ablation: drop the `if fault is not None:` arm and this reddens twice — with `0`
    for the estimate, because the degraded empty text has no open ids, and with no
    `sweep-remaining-estimate-unreadable` row."""
    install_bmad_config(project)
    engine, _ = make_sweep(project, [])
    project.deferred_work.write_bytes(b"# Deferred Work\n\n### DW-1: bad \xff byte\n")

    assert engine._remaining_estimate() is None

    faults = [
        e for e in engine.journal.entries() if e["kind"] == "sweep-remaining-estimate-unreadable"
    ]
    assert len(faults) == 1
    assert faults[0]["ledger"] == str(project.deferred_work)
    assert faults[0]["error"].startswith("UnicodeDecodeError: ")


def resume_sweep(project, engine, script, answers=(), prompting=False, **kwargs):
    state = load_state(engine.run_dir)
    state.clear_pause()
    adapter = MockAdapter(script)
    inputs = iter(answers)
    prompter = DecisionPrompter(input_fn=lambda _: next(inputs), print_fn=lambda _line: None)
    new_engine = SweepEngine(
        paths=project,
        policy=engine.policy,
        adapter=adapter,
        run_dir=engine.run_dir,
        # A real resume REOPENS the journal: `cli.cmd_resume` builds a fresh
        # `Journal(run_dir)` and hands it to `runsetup.compose_resume`, and this
        # harness must build the same shape (DW-215). Not for the reason that entry
        # gives — `Journal` keeps no in-memory record list: both objects persist and
        # reread records from disk. Their log metadata can differ because the shared
        # object carries `_log_task`/`_log_path`: see the row below.
        journal=Journal(engine.run_dir),
        state=state,
        prompting=prompting,
        prompter=prompter,
        **kwargs,
    )
    return new_engine, adapter


def test_the_resumed_engine_reopens_the_journal_off_disk(project):
    """The harness's own fidelity: `resume_sweep` builds the journal a REAL resume
    builds rather than handing the pre-pause engine's object back (DW-215).

    `cli.cmd_resume` constructs `Journal(run_dir)` and passes it to
    `runsetup.compose_resume`, and a fresh `Journal` starts with
    `_log_task = None`. Sharing one object carried the PRE-PAUSE session's
    `set_active_log` binding across the resume boundary, and `Journal.append` stamps
    `log_task`/`log_pos` onto every entry while that binding is set — so every row a
    resumed engine writes BEFORE starting its own session (a replay pre-pass, a
    resume-carry, a cycle row) was stamped with a log from the run before the pause.
    A real resume writes those rows bare. That divergence is the whole defect the
    reopen closes.

    DW-215's ledger entry states the mechanism wrongly — "one shared in-memory
    collector" — and the correction belongs here so the false reading cannot come
    back. `Journal` holds NO in-memory record list: `append` opens
    `run_dir/journal.jsonl` and writes one line, `entries()` re-reads that file, and
    the `journal_text`/`_records` helpers below read it directly. Both shared and
    reopened objects persist and reread records from disk, although their log metadata
    can differ. Every "announced exactly once" claim in the resume rows was ALREADY
    round-tripping through disk. Those claims were never at risk;
    `_log_task`/`_log_path` are the only mutable state a shared object could leak.

    Graded on the CONSEQUENCE, never on object identity: `resumed.journal is not
    engine.journal` would be tautological, and it would red for a refactor that
    changed nothing observable.

    Ablation, performed: revert this helper to `journal=engine.journal` and the FINAL
    assertion reds — the appended row carries the pre-pause `log_task` and `log_pos`.
    That one only. The two `first[...]` lines above it are the PREMISE and stay green
    under both spellings, because they describe the pre-pause row, which is stamped
    either way; and pytest stops at the first failing statement regardless. The
    reopen half stays green under the revert too, which is exactly the point above:
    it is file-backed either way."""
    engine, _ = make_sweep(project, [])
    engine.journal.set_active_log("dw-fix")  # stands in for the pre-pause session
    engine.journal.append("sweep-cycle", cycle=1)
    save_state(engine.run_dir, engine.state)

    resumed, _ = resume_sweep(project, engine, [])

    # reopened, not re-created: the rows already on disk are still what it reads
    assert [e["kind"] for e in resumed.journal.entries()] == ["sweep-cycle"]
    resumed.journal.append("sweep-cycle", cycle=2)
    first, second = _records(resumed, "sweep-cycle")
    assert (first["cycle"], second["cycle"]) == (1, 2)  # appended AFTER, same file
    assert first["log_task"] == "dw-fix"  # premise: the pre-pause row WAS stamped...
    # ...with BOTH fields, so the conclusion below pins both. `0` is deliberate: it is
    # `append`'s `except OSError: size = 0` arm, since no pane log exists on disk here.
    assert first["log_pos"] == 0
    assert "log_task" not in second and "log_pos" not in second


def journal_text(engine) -> str:
    return (engine.run_dir / "journal.jsonl").read_text()


def ledger_entries(project) -> dict:
    return {
        e.id: e
        for e in deferredwork.parse_ledger(project.deferred_work.read_text(encoding="utf-8"))
    }


def _records(engine, kind: str) -> list[dict]:
    """Every journal record of `kind` the run wrote, in order."""
    records = [json.loads(line) for line in journal_text(engine).splitlines() if line.strip()]
    return [r for r in records if r.get("kind") == kind]


def _mismatches(engine) -> list[dict]:
    """Every `sweep-decision-option-mismatch` record the run wrote, in order."""
    return _records(engine, "sweep-decision-option-mismatch")


